<script setup lang="ts">import {ref,onMounted} from 'vue';import {go} from '../router';import {studies} from '../stores/studies';import {datasets} from '../stores/datasets';import {instruments} from '../stores/instruments';import {runs} from '../stores/runs';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import {compatibleUnits,unitError,conversionFactor,unitNote} from '../constants/enums';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';const name=ref(''),datasetId=ref('demo-dataset'),instrumentId=ref('demo-instrument'),ratio=ref(2.25),tolerance=ref(2);const {error,busy,act}=useTask();
const currentDataset=ref<any>(undefined);function datasetChanged(){currentDataset.value=datasets.items.value.find((r:any)=>r.id===datasetId.value)}
const conflict=ref('');const basis=ref('');function refreshUnits(){const d=currentDataset.value;const i=instruments.items.value.find((r:any)=>r.id===instrumentId.value);conflict.value='';basis.value='';if(!d||!i)return;if(!compatibleUnits(d.x_unit,i.unit)){conflict.value=unitError(d.x_unit,i.unit);return}if(!compatibleUnits(d.y_unit,i.unit)){conflict.value=unitError(d.y_unit,i.unit);return}basis.value=`分析单位 ${i.unit}：X侧 ${d.x_unit}→${i.unit} × ${conversionFactor(d.x_unit,i.unit)}；Y侧 ${d.y_unit}→${i.unit} × ${conversionFactor(d.y_unit,i.unit)}；λ按 (y_factor/x_factor)² 调整`}
onMounted(()=>Promise.all([studies.load(),datasets.load(),instruments.load()]).then(()=>{datasetChanged();refreshUnits()}));
function submit(){act(async()=>{const d=currentDataset.value;const i=instruments.items.value.find((r:any)=>r.id===instrumentId.value);if(!d||!i)throw new Error('请选择配对批次与探头组合');if(!compatibleUnits(d.x_unit,i.unit)||!compatibleUnits(d.y_unit,i.unit))throw new Error(conflict.value||'单位不兼容');await studies.create({name:name.value,dataset_id:datasetId.value,instrument_id:instrumentId.value,variance_ratio:ratio.value,tolerance:tolerance.value});name.value=''})}function execute(id:string){act(async()=>{const run=await runs.create({study_id:id});go('/results?run='+run.id)})}</script>
<template><PageHeading index="03 / 研究设定" title="误差方差比，是输入，不是拟合结论。" note="λ=var(y测量误差)/var(x测量误差)，按批次两侧原单位输入；分析换算到探头组合单位时λ随 (y_factor/x_factor)² 调整。讨论容差按分析单位解释，不改变BA界限。"/><Notice :message="error"/><div class="two-col"><section><article v-for="r in studies.items.value" :key="r.id" class="study-row"><p class="eyebrow">CALIBRATION STUDY</p><h2>{{r.name}}</h2><dl><div><dt>方差比 λ</dt><dd>{{r.variance_ratio}}</dd></div><div><dt>讨论容差 ±</dt><dd>{{r.tolerance}}</dd></div><div><dt>BA样本SD</dt><dd>ddof=1</dd></div></dl><button v-if="canWrite()" :disabled="busy" @click="execute(r.id)">执行后台校准 →</button></article></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>新建校准研究</h2><label>研究名称<input v-model="name" required minlength="2"></label><label>配对批次<select v-model="datasetId" @change="datasetChanged();refreshUnits()"><option v-for="r in datasets.items.value" :key="r.id" :value="r.id">{{r.name}}（{{r.x_unit}}/{{r.y_unit}}）</option></select></label><label>探头组合<select v-model="instrumentId" @change="refreshUnits"><option v-for="r in instruments.items.value" :key="r.id" :value="r.id">{{r.name}}（{{r.unit}}）</option></select></label><p class="unit-hint" :class="{conflict:!!conflict}">{{conflict||basis||unitNote}}</p><label>误差方差比 λ（按批次原单位）<input type="number" v-model.number="ratio" min=".000001" max="1000000" step="any" required></label><label>讨论容差（按分析单位）<input type="number" v-model.number="tolerance" min=".000001" max="1000000" step="any" required></label><button :disabled="busy||!!conflict">保存研究设定</button></form></div></template>
